  baseline.forEach((l) => {
    l.route = routes[`baseline:${l.id}:light`] || [];
  });
  redesigned.forEach((l) => {
    l.route = routes[`redesigned:${l.id}:light`] || [];
  });
  function get(mode, id, direction = "light") {
    const source = (mode === "baseline" ? baseline : redesigned)[
      Math.max(1, Math.min(10, id)) - 1
    ];
    const data = JSON.parse(JSON.stringify(source));
    data.direction = direction;
    if (mode !== "baseline" && data.mechanic) {
      if (direction === "light") {
        data.mechanicHint =
          "Place a lantern above your perch. Hunters gather within its visible radius.";
        // Clusters near the staging shelf make lure placement change the approach route.
        if (id === 3) data.pumpkins = [pumpkin(-1, 3), pumpkin(0.3, 3.8)];
        if (id === 6)
          data.pumpkins = [
            pumpkin(-0.5, 4.7),
            pumpkin(1, 5.3),
            pumpkin(2, 7.8),
          ];
        if (id === 10) data.pumpkins = [pumpkin(-1, 5), pumpkin(1, 5)];
      } else if (direction === "shadow") {
        data.mechanicHint =
          "Record one flight, then replay its shadow through the marked switch. A live rabbit cannot trigger it.";
        data.switches = [{ x: -2, y: 2, r: 0.85 }];
        data.gate = {
          x: 2,
          y: id === 10 ? 7 : 2.5,
          w: 0.45,
          h: id === 10 ? 3 : 5,
        };
        if (id === 6) data.switches.push({ x: 0, y: 4, r: 0.85 });
        // Recording flights from a broad shelf avoids requiring a moving perch.
        data.platforms.push(ledge(-3, 3, 4));
      } else if (direction === "bell") {
        data.mechanicHint =
          "The visible bell changes phase every four seconds. Read the next surface before launching.";
        data.bellPeriod = 8;
        data.platforms.push({
          ...ledge(0, id === 10 ? 8 : 4, 2.5),
          phase: 0,
          type: "ghost",
          period: 8,
        });
        data.platforms.push({
          ...ledge(1, id === 10 ? 10 : 5.5, 2.5),
          phase: 1,
          type: "ghost",
          period: 8,
          phaseOffset: 0.5,
        });
        data.pumpkins.forEach((p, i) => {
          p.phase = i % 2;
        });
      }
    }
    data.route =
      routes[`${mode}:${id}:${direction}`] ||
      routes[`${mode}:${id}:light`] ||
      [];
    return data;
  }
  return { baseline, redesigned, get };
